  `IconPath` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `IsParent` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `IsDefault` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
